export default `@charset "UTF-8";:root{--cosma-primary: #000000;--cosma-secondary: #D32F2F;--cosma-accent: #D4AF37;--cosma-bg-light: #FFFFFF;--cosma-bg-dark: #121212;--cosma-text-dark: #212121;--cosma-text-light: #FFFFFF;--cosma-text-gold: #D4AF37;--font-family-sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;--font-family-serif: "Playfair Display", Georgia, "Times New Roman", serif}body{margin:0;font-family:var(--font-family-sans);background-color:var(--cosma-bg-light);color:var(--cosma-text-dark);-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;display:flex;flex-direction:column;min-height:100vh}app-root{display:flex;flex-direction:column;flex-grow:1}body.login-page{justify-content:center;align-items:center;background:linear-gradient(135deg,#000,#434343)}h1,h2,h3,h4,h5,h6{font-family:var(--font-family-serif);color:var(--cosma-primary);margin-top:0}a{text-decoration:none;color:inherit;transition:color .3s ease}a:hover{color:var(--cosma-accent)}button{cursor:pointer;font-family:var(--font-family-sans)}.container{max-width:1200px;margin:0 auto;padding:0 1rem}.text-primary{color:var(--cosma-primary)}.text-secondary{color:var(--cosma-secondary)}.text-accent{color:var(--cosma-accent)}.text-gold{color:var(--cosma-text-gold)}.bg-primary{background-color:var(--cosma-primary);color:var(--cosma-text-light)}.bg-secondary{background-color:var(--cosma-secondary);color:var(--cosma-text-light)}.bg-accent{background-color:var(--cosma-accent);color:var(--cosma-primary)}
`;